import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Autowired,
  ApiQueryParams,
  reply,
  type Ctx,
} from '@forinda/kickjs'
import { TaskService } from './task.service'
import { createTaskSchema } from './dtos/create-task.dto'
import { updateTaskSchema } from './dtos/update-task.dto'
import { TASK_QUERY_CONFIG } from './task.constants'

// Each handler annotates its `ctx` with `Ctx<KickRoutes.TaskController['<method>']>`
// so `ctx.params`, `ctx.body`, and `ctx.query` are typed end-to-end.
// The `KickRoutes` namespace is generated by `kick typegen` (auto-run on
// `kick dev`) — see https://kickjs.app/guide/typegen.
//
// Handlers RETURN their payload rather than calling `ctx.json()`: the runtime
// auto-sends it, and `kick typegen` reads the return type to fill in
// `KickRoutes[...].response` — which is what makes the typed client know what
// each route gives back. A handler that writes via `ctx.json()` and returns
// nothing infers as `unknown`. Use `reply(status, body)` (or the
// `reply.created` / `reply.noContent` sugars) when the status isn't 200, and
// `ctx.problem.*` for error branches — those send immediately and return
// nothing, so they stay out of the success type.

@Controller()
export class TaskController {
  @Autowired() private readonly taskService!: TaskService

  @Get('/')
  @ApiQueryParams(TASK_QUERY_CONFIG)
  async list(ctx: Ctx<KickRoutes.TaskController['list']>) {
    return ctx.paginate((parsed) => this.taskService.findPaginated(parsed), TASK_QUERY_CONFIG)
  }

  @Get('/:id')
  async getById(ctx: Ctx<KickRoutes.TaskController['getById']>) {
    const result = await this.taskService.findById(ctx.params.id)
    if (!result) {
      // Sends RFC 9457 problem+json now; returning nothing keeps the 404 out
      // of this route's inferred response type.
      ctx.problem.notFound({ detail: `Task ${ctx.params.id} not found` })
      return
    }
    return result
  }

  @Post('/', { body: createTaskSchema, name: 'CreateTask' })
  async create(ctx: Ctx<KickRoutes.TaskController['create']>) {
    return reply.created(await this.taskService.create(ctx.body))
  }

  @Put('/:id', { body: updateTaskSchema, name: 'UpdateTask' })
  async update(ctx: Ctx<KickRoutes.TaskController['update']>) {
    return this.taskService.update(ctx.params.id, ctx.body)
  }

  @Delete('/:id')
  async remove(ctx: Ctx<KickRoutes.TaskController['remove']>) {
    await this.taskService.delete(ctx.params.id)
    return reply.noContent()
  }
}
